# Provisions Firezone accounts and their actors, authentication providers,
# sites, groups, resources and policies from the json file generated by the
# NixOS module. This script is evaluated inside the running portal via
# `portal rpc`.
#
# Provisioned entities are tracked by their UUID in `provision-uuids.json` in
# the working directory, keyed by the attribute names used in the NixOS
# configuration, so they can be updated or removed on subsequent runs.
defmodule Provision do
  alias Portal.{Account, Actor, AuthProvider, Group, Membership, Policy, Repo, Resource, Site}
  alias Portal.EmailOTP.AuthProvider, as: EmailOTPAuthProvider
  alias Portal.OIDC.AuthProvider, as: OIDCAuthProvider
  alias Portal.Userpass.AuthProvider, as: UserpassAuthProvider

  import Ecto.Changeset
  import Ecto.Query
  require Logger

  @provision_file "/run/firezone/provision.json"

  # Mapping keys are kept compatible with the previous provisioning
  # implementation so existing deployments keep tracking their entities.
  defmodule Mapping do
    @moduledoc false
    @mapping_file "provision-uuids.json"

    def load do
      mapping =
        with {:ok, content} <- File.read(@mapping_file),
             {:ok, mapping} <- JSON.decode(content) do
          mapping
        else
          _ -> %{"accounts" => %{}}
        end

      Process.put(:provision_mapping, mapping)
    end

    def save do
      File.write!(@mapping_file, JSON.encode!(Process.get(:provision_mapping)))
    end

    def account_slugs, do: Map.keys(get(["accounts"]) || %{})
    def account_id(slug), do: get(["accounts", slug, "id"])
    def entities(slug, type), do: get(["accounts", slug, type]) || %{}
    def entity(slug, type, key), do: get(["accounts", slug, type, key])

    def put_account(slug, id) do
      update(fn mapping ->
        account = Map.put(get_in(mapping, ["accounts", slug]) || %{}, "id", id)
        put_in(mapping, ["accounts", slug], account)
      end)
    end

    def put_entity(slug, type, key, id) do
      update(fn mapping ->
        account = get_in(mapping, ["accounts", slug]) || %{}
        entities = Map.put(Map.get(account, type) || %{}, key, id)
        put_in(mapping, ["accounts", slug], Map.put(account, type, entities))
      end)
    end

    def delete_account(slug) do
      update(fn mapping -> update_in(mapping, ["accounts"], &Map.delete(&1, slug)) end)
    end

    def delete_entity(slug, type, key) do
      update(fn mapping ->
        update_in(mapping, ["accounts", slug, type], &Map.delete(&1 || %{}, key))
      end)
    end

    defp get(path), do: get_in(Process.get(:provision_mapping), path)
    defp update(fun), do: Process.put(:provision_mapping, fun.(Process.get(:provision_mapping)))
  end

  def run do
    Logger.info("Starting provisioning")

    %{"accounts" => accounts} = @provision_file |> File.read!() |> JSON.decode!()
    Mapping.load()

    case Repo.transaction(fn -> provision(accounts) end, timeout: :infinity) do
      {:ok, _} ->
        Mapping.save()
        Logger.info("Provisioning completed successfully")

      {:error, reason} ->
        raise "Provisioning failed, no changes were applied: #{inspect(reason)}"
    end
  end

  defp provision(accounts) do
    # Remove accounts which are no longer configured
    for slug <- Mapping.account_slugs() -- Map.keys(accounts) do
      if account = fetch(Account, Mapping.account_id(slug)) do
        Logger.info("Deleting removed account #{slug}")
        Repo.delete!(account)
      end

      Mapping.delete_account(slug)
    end

    for {slug, account_data} <- accounts do
      account = sync_account(slug, account_data)
      cleanup_entities(slug, account, account_data)

      for {key, data} <- Map.get(account_data, "actors", %{}), do: sync_actor(account, key, data)
      for {key, data} <- Map.get(account_data, "auth", %{}), do: sync_provider(account, key, data)
      for {key, data} <- Map.get(account_data, "gatewayGroups", %{}), do: sync_site(account, key, data)
      for {key, data} <- Map.get(account_data, "groups", %{}), do: sync_group(account, key, data)
      for {key, data} <- Map.get(account_data, "resources", %{}), do: sync_resource(account, key, data)
      for {key, data} <- Map.get(account_data, "policies", %{}), do: sync_policy(account, key, data)

      if map_size(Map.get(account_data, "relayGroups", %{})) > 0 do
        Logger.warning("Relay groups are no longer supported and will be ignored. Relays are now global.")
      end
    end
  end

  ## Accounts

  defp sync_account(slug, data) do
    attrs =
      %{
        name: data["name"],
        legal_name: Map.get(data, "legal_name", data["name"]),
        features: Map.get(data, "features", %{}),
        limits: Map.get(data, "limits", %{}),
        metadata: Map.get(data, "metadata", %{})
      }
      |> maybe_put(:config, data["config"])

    case fetch(Account, Mapping.account_id(slug)) || Repo.get_by(Account, slug: slug) do
      nil ->
        Logger.info("Creating account #{slug}")

        account =
          %Account{}
          |> cast(Map.put(attrs, :slug, slug), [:name, :legal_name, :slug])
          |> put_change(:key, Account.new_key())
          |> cast_account_embeds(attrs)
          |> Account.changeset()
          |> Repo.insert!()

        Mapping.put_account(slug, account.id)
        create_account_defaults(slug, account)
        account

      account ->
        Logger.info("Updating account #{slug}")
        Mapping.put_account(slug, account.id)

        account
        |> cast(attrs, [:name, :legal_name])
        |> cast_account_embeds(attrs)
        |> Account.changeset()
        |> Repo.update!()
    end
  end

  defp cast_account_embeds(changeset, attrs) do
    changeset
    |> cast_embed(:features)
    |> cast_embed(:limits)
    |> cast_embed(:metadata)
    |> then(fn cs -> if Map.has_key?(attrs, :config), do: cast_embed(cs, :config), else: cs end)
  end

  # Mirrors what the portal creates for accounts which sign up via the web UI
  defp create_account_defaults(slug, account) do
    Logger.info("Creating default entities for account #{slug}")

    everyone_group =
      %Group{account_id: account.id}
      |> cast(%{name: "Everyone", type: :managed}, [:name, :type])
      |> Group.changeset()
      |> Repo.insert!()

    Mapping.put_entity(slug, "actor_groups", "everyone", everyone_group.id)

    internet_site =
      %Site{account_id: account.id}
      |> cast(%{name: "Internet", managed_by: :system}, [:name, :managed_by])
      |> Site.changeset()
      |> Repo.insert!()

    %Resource{account_id: account.id, site_id: internet_site.id}
    |> cast(%{name: "Internet", type: :internet}, [:name, :type])
    |> validate_required([:name, :type])
    |> Repo.insert!()

    create_builtin_provider(account, :email_otp, EmailOTPAuthProvider, "Email (OTP)")
    create_builtin_provider(account, :userpass, UserpassAuthProvider, "Username & Password")
  end

  defp create_builtin_provider(account, type, module, name) do
    id = Ecto.UUID.generate()

    %AuthProvider{}
    |> cast(%{id: id, account_id: account.id, type: type}, [:id, :account_id, :type])
    |> AuthProvider.changeset()
    |> Repo.insert!()

    struct(module)
    |> cast(%{id: id, account_id: account.id, name: name, context: :clients_and_portal}, [
      :id,
      :account_id,
      :name,
      :context
    ])
    |> module.changeset()
    |> Repo.insert!()
  end

  ## Cleanup of removed entities

  defp cleanup_entities(slug, account, data) do
    configured = %{
      "actors" => Map.keys(Map.get(data, "actors", %{})),
      "providers" => Map.keys(Map.get(data, "auth", %{})),
      "gateway_groups" => Map.keys(Map.get(data, "gatewayGroups", %{})),
      "actor_groups" => ["everyone" | Map.keys(Map.get(data, "groups", %{}))],
      "resources" => Map.keys(Map.get(data, "resources", %{})),
      "policies" => Map.keys(Map.get(data, "policies", %{}))
    }

    # Policies reference groups and resources, resources reference sites
    for {type, schema} <- [
          {"policies", Policy},
          {"resources", Resource},
          {"actor_groups", Group},
          {"gateway_groups", Site},
          {"providers", AuthProvider},
          {"actors", Actor}
        ],
        {key, id} <- Mapping.entities(slug, type),
        key not in configured[type] do
      if entity = fetch(schema, account, id) do
        Logger.info("Deleting removed #{type} entry #{key}")
        Repo.delete!(entity)
      end

      Mapping.delete_entity(slug, type, key)
    end

    # Relay groups are no longer tracked
    for {key, _id} <- Mapping.entities(slug, "relay_groups") do
      Mapping.delete_entity(slug, "relay_groups", key)
    end
  end

  ## Actors

  defp sync_actor(account, key, data) do
    type = String.to_existing_atom(data["type"])

    attrs =
      if type in [:service_account, :api_client] do
        %{type: type, name: data["name"]}
      else
        %{
          type: type,
          name: data["name"],
          email: data["email"],
          password_hash: data["passwordHash"],
          allow_email_otp_sign_in: true
        }
      end

    fields = Map.keys(attrs)

    existing =
      fetch(Actor, account, Mapping.entity(slug(account), "actors", key)) ||
        adopt(Actor, account, "actors", key, if(attrs[:email], do: [email: String.downcase(attrs.email)]))

    case existing do
      nil ->
        Logger.info("Creating actor #{key}")

        actor =
          %Actor{account_id: account.id}
          |> cast(attrs, fields)
          |> Actor.changeset()
          |> Repo.insert!()

        Mapping.put_entity(slug(account), "actors", key, actor.id)

      actor ->
        Logger.info("Updating actor #{key}")

        actor
        |> cast(attrs, fields)
        |> Actor.changeset()
        |> Repo.update!()
    end
  end

  ## Authentication providers

  defp sync_provider(account, key, %{"adapter" => "oidc"} = data) do
    config = Map.get(data, "adapter_config", %{})

    attrs =
      %{
        name: data["name"],
        issuer: config["issuer"],
        client_id: config["client_id"],
        client_secret: config["client_secret"],
        discovery_document_uri: config["discovery_document_uri"],
        context: Map.get(config, "context", "clients_and_portal"),
        # The web UI verifies the configuration by signing in once, we trust the
        # declarative configuration instead.
        is_verified: true
      }
      |> maybe_put(:client_session_lifetime_secs, config["client_session_lifetime_secs"])
      |> maybe_put(:portal_session_lifetime_secs, config["portal_session_lifetime_secs"])
      |> maybe_put(:email_verification_method, config["email_verification_method"])

    fields = Map.keys(attrs)

    existing =
      fetch(AuthProvider, account, Mapping.entity(slug(account), "providers", key)) ||
        adopt_oidc_provider(account, key, attrs.client_id)

    case existing do
      nil ->
        Logger.info("Creating OIDC provider #{key}")
        id = Ecto.UUID.generate()

        %AuthProvider{}
        |> cast(%{id: id, account_id: account.id, type: :oidc}, [:id, :account_id, :type])
        |> AuthProvider.changeset()
        |> Repo.insert!()

        %OIDCAuthProvider{}
        |> cast(Map.merge(attrs, %{id: id, account_id: account.id}), [:id, :account_id | fields])
        |> OIDCAuthProvider.changeset()
        |> Repo.insert!()

        Mapping.put_entity(slug(account), "providers", key, id)

      %AuthProvider{type: :oidc, id: id} ->
        Logger.info("Updating OIDC provider #{key}")

        Repo.get!(OIDCAuthProvider, id)
        |> cast(attrs, fields)
        |> OIDCAuthProvider.changeset()
        |> Repo.update!()

      %AuthProvider{type: type} ->
        raise "Provider #{key} has type #{type} and cannot be changed to oidc, remove and re-add it instead"
    end
  end

  defp sync_provider(_account, key, %{"adapter" => adapter}) do
    raise "Unsupported auth adapter '#{adapter}' for provider #{key}"
  end

  ## Sites

  defp sync_site(account, key, data) do
    existing =
      fetch(Site, account, Mapping.entity(slug(account), "gateway_groups", key)) ||
        adopt(Site, account, "gateway_groups", key, name: data["name"], managed_by: :account)

    case existing do
      nil ->
        Logger.info("Creating site #{key}")

        site =
          %Site{account_id: account.id}
          |> cast(%{name: data["name"]}, [:name])
          |> Site.changeset()
          |> Repo.insert!()

        Mapping.put_entity(slug(account), "gateway_groups", key, site.id)

      site ->
        Logger.info("Updating site #{key}")

        site
        |> cast(%{name: data["name"]}, [:name])
        |> Site.changeset()
        |> Repo.update!()
    end
  end

  ## Groups

  defp sync_group(account, key, data) do
    existing =
      fetch(Group, account, Mapping.entity(slug(account), "actor_groups", key)) ||
        adopt(Group, account, "actor_groups", key, name: data["name"])

    group =
      case existing do
        nil ->
          Logger.info("Creating group #{key}")

          group =
            %Group{account_id: account.id}
            |> cast(%{name: data["name"], type: :static}, [:name, :type])
            |> Group.changeset()
            |> Repo.insert!()

          Mapping.put_entity(slug(account), "actor_groups", key, group.id)
          group

        group ->
          Logger.info("Updating group #{key}")

          group
          |> cast(%{name: data["name"]}, [:name])
          |> Group.changeset()
          |> Repo.update!()
      end

    existing_members =
      Repo.all(from m in Membership, where: m.group_id == ^group.id, select: m.actor_id)

    desired_members =
      Enum.map(Map.get(data, "members", []), fn member ->
        Mapping.entity(slug(account), "actors", member) ||
          raise "Cannot find provisioned actor #{member} to add to group #{key}"
      end)

    for actor_id <- desired_members -- existing_members do
      Logger.info("Adding member to group #{key}")

      %Membership{account_id: account.id, group_id: group.id, actor_id: actor_id}
      |> change()
      |> Membership.changeset()
      |> Repo.insert!()
    end

    if data["forceMembers"] == true do
      removed_members = existing_members -- desired_members

      if removed_members != [] do
        Logger.info("Removing #{length(removed_members)} untracked members from group #{key}")

        from(m in Membership, where: m.group_id == ^group.id and m.actor_id in ^removed_members)
        |> Repo.delete_all()
      end
    end
  end

  ## Resources

  defp sync_resource(account, key, data) do
    [gateway_group | _] = data["gatewayGroups"]

    site_id =
      Mapping.entity(slug(account), "gateway_groups", gateway_group) ||
        raise "Cannot find provisioned gateway group #{gateway_group} for resource #{key}"

    attrs = %{
      type: data["type"],
      name: data["name"],
      address: data["address"],
      address_description: data["addressDescription"],
      site_id: site_id,
      filters:
        Enum.map(Map.get(data, "filters", []), fn filter ->
          %{protocol: filter["protocol"], ports: Map.get(filter, "ports", [])}
        end)
    }

    fields = [:type, :name, :address, :address_description, :site_id]

    existing =
      fetch(Resource, account, Mapping.entity(slug(account), "resources", key)) ||
        adopt(Resource, account, "resources", key, name: data["name"])

    case existing do
      nil ->
        Logger.info("Creating resource #{key}")

        resource =
          %Resource{account_id: account.id}
          |> cast(attrs, fields)
          |> Resource.changeset()
          |> Repo.insert!()

        Mapping.put_entity(slug(account), "resources", key, resource.id)

      resource ->
        Logger.info("Updating resource #{key}")

        resource
        |> cast(attrs, fields)
        |> Resource.changeset()
        |> Repo.update!()
    end
  end

  ## Policies

  defp sync_policy(account, key, data) do
    attrs = %{
      description: data["description"],
      group_id:
        Mapping.entity(slug(account), "actor_groups", data["group"]) ||
          raise("Cannot find provisioned group #{data["group"]} for policy #{key}"),
      resource_id:
        Mapping.entity(slug(account), "resources", data["resource"]) ||
          raise("Cannot find provisioned resource #{data["resource"]} for policy #{key}")
    }

    fields = Map.keys(attrs)

    existing =
      fetch(Policy, account, Mapping.entity(slug(account), "policies", key)) ||
        adopt(Policy, account, "policies", key,
          group_id: attrs.group_id,
          resource_id: attrs.resource_id
        )

    case existing do
      nil ->
        Logger.info("Creating policy #{key}")

        policy =
          %Policy{account_id: account.id}
          |> cast(attrs, fields)
          |> Policy.changeset()
          |> Repo.insert!()

        Mapping.put_entity(slug(account), "policies", key, policy.id)

      policy ->
        Logger.info("Updating policy #{key}")

        policy
        |> cast(attrs, fields)
        |> Policy.changeset()
        |> Repo.update!()
    end
  end

  ## Helpers

  # Entities which are not tracked yet are adopted when they match a unique
  # natural key, so provisioning can take over existing entities and upgrades
  # from older state files don't run into unique constraints.
  defp adopt(_schema, _account, _type, _key, nil), do: nil

  defp adopt(schema, account, type, key, clauses) do
    case Repo.get_by(schema, [account_id: account.id] ++ clauses) do
      nil -> nil
      entity -> adopt_existing(schema, account, type, key, entity.id)
    end
  end

  # OIDC providers are matched by their client id, which is unique per account
  defp adopt_oidc_provider(account, key, client_id) do
    case Repo.get_by(OIDCAuthProvider, account_id: account.id, client_id: client_id) do
      nil -> nil
      provider -> adopt_existing(AuthProvider, account, "providers", key, provider.id)
    end
  end

  defp adopt_existing(schema, account, type, key, id) do
    Logger.info("Adopting existing #{type} entry #{key}")
    Mapping.put_entity(slug(account), type, key, id)
    fetch(schema, account, id)
  end

  defp slug(%Account{slug: slug}), do: slug

  defp fetch(_schema, nil), do: nil
  defp fetch(schema, id), do: Repo.get(schema, id)

  defp fetch(_schema, _account, nil), do: nil
  defp fetch(schema, account, id), do: Repo.get_by(schema, account_id: account.id, id: id)

  defp maybe_put(map, _key, nil), do: map
  defp maybe_put(map, key, value), do: Map.put(map, key, value)
end

Provision.run()
